{"query": "SELECT s AS study, mutation_type, sum(altered_samples) AS samples, count() AS distinct_variants, max(profiled_samples) AS profiled FROM (
SELECT 'LUAD' AS s, * FROM gene_mutation_variants_in_study(study='luad_tcga_pan_can_atlas_2018', gene='EGFR')
UNION ALL
SELECT 'LUSC' AS s, * FROM gene_mutation_variants_in_study(study='lusc_tcga_pan_can_atlas_2018', gene='EGFR')
) GROUP BY s, mutation_type ORDER BY s, samples DESC"}
